function getMessageTemplate(locale, key) {
  return APP_MESSAGES[locale]?.[key] ?? APP_MESSAGES.en[key] ?? key;
}

export function translateAppMessage(locale, key, params = {}) {
  const template = getMessageTemplate(locale, key);
  return String(template).replace(/\{\{\s*(\w+)\s*\}\}/g, (_, name) => (
    Object.prototype.hasOwnProperty.call(params, name) ? String(params[name]) : ''
  ));
}

export function localizeStaticUiText(locale, text) {
  const value = String(text ?? '');
  const trimmed = value.trim();
  if (!trimmed || locale === 'en') return value;
  const translated = STATIC_UI_MESSAGES[locale]?.[trimmed];
  if (!translated || translated === trimmed) return value;
  const prefix = value.match(/^\s*/)?.[0] || '';
  const suffix = value.match(/\s*$/)?.[0] || '';
  return `${prefix}${translated}${suffix}`;
}
